// IQ grid tables, verbatim from llama.cpp ggml/src/ggml-common.h
// (Apache-2.0, https://github.com/ggerganov/llama.cpp, commit 9581154).
// These are the STATIC literal tables the ggml dequantizers index
// (dequantize_row_iq2_xxs / iq2_xs / iq3_xxs / iq1_s / iq1_m in
// ggml-quants.c). They are NOT the runtime grids built by ggml's
// iq2xs_init_impl / iq3xs_init_impl (those feed only the *quantizers*,
// which also need an importance matrix); the dequant codebooks below
// are what a real GGUF file's bytes decode through, so the dequantizers
// in this file index these tables directly. Values differ from the
// quantizer-side grids on purpose: e.g. iq2xxs_grid bytes are {8, 25,
// 43} where the quantizer grid is {1, 3, 5} — the block scale absorbs
// the ratio, and the encoders below search THESE tables, so encode and
// decode agree exactly.
// IQ1S_DELTA is ggml's 0.125f (ggml-common.h).
// ============================================================================
